<?php

  // relation - Checks already-shaped named rowsets. Schema primary is a list of `{table,fields}`; foreign entries are `{table,fields,references:{table,fields},null:"error"|"skip"}`. Composite scalar keys preserve PHP types, including integer vs string and boolean vs integer; no coercion. Primary keys cannot be null; foreign skip ignores a row with any null key component, while missing fields always fail. Returns the first deterministic issue with quoted table/row path. ≤100 tables, 10000 total rows, 100 declarations, 16 key fields and 1000000 key-field checks, 8 MiB aggregate key bytes, 4096 bytes per string key component and 256 bytes per table/field name. Row shape remains the rowset kind’s responsibility.
  //
  // Runnable example: `apps/tags/examples/schema/relation.pad`. Independent fixture: `php tests/subsystems/expansion-schemas-relation.php`.

return ['call'=>function($tables,$schema){
 $fail=fn($path,$code,$message)=>['valid'=>FALSE,'issues'=>[padSchemaIssue($path,$code,$message)],'kind'=>'relation'];
 if(!is_array($tables)||count($tables)>100||!is_array($schema)||array_diff(array_keys($schema),['primary','foreign']))return $fail('schema','schema','expected named rowsets and primary/foreign declarations');
 $total=0;foreach($tables as $name=>$rows){if(!is_string($name)||strlen($name)>256||!mb_check_encoding($name,'UTF-8')||!is_array($rows)||!array_is_list($rows)||($total+=count($rows))>10000)return $fail('$','limit','at most 100 named rowsets and 10000 total rows');foreach($rows as $i=>$row)if(!is_array($row))return $fail('$['.json_encode($name).']['.$i.']','type','row must be a record');}
 $primary=$schema['primary']??[];$foreign=$schema['foreign']??[];if(!is_array($primary)||!array_is_list($primary)||!is_array($foreign)||!array_is_list($foreign)||count($primary)+count($foreign)>100)return $fail('schema','schema','at most 100 primary and foreign declarations');
 $valid=function($def)use($tables){return is_array($def)&&is_string($def['table']??NULL)&&array_key_exists($def['table'],$tables)&&is_array($def['fields']??NULL)&&array_is_list($def['fields'])&&count($def['fields'])>0&&count($def['fields'])<=16&&array_reduce($def['fields'],fn($ok,$f)=>$ok&&is_string($f)&&$f!==''&&strlen($f)<=256&&mb_check_encoding($f,'UTF-8'),TRUE)&&count(array_unique($def['fields'],SORT_STRING))===count($def['fields']);};
 $work=0;$bytes=0;$key=function($row,$fields)use(&$work,&$bytes){$values=[];$hasNull=FALSE;foreach($fields as $field){if(++$work>1000000)throw new InvalidArgumentException('relation key work exceeds 1000000');if(!array_key_exists($field,$row))return ['missing',NULL];$v=$row[$field];if($v===NULL){$hasNull=TRUE;continue;}if((!is_scalar($v))||(is_float($v)&&!is_finite($v)))return ['type',NULL];if(is_string($v)&&(strlen($v)>4096||!mb_check_encoding($v,'UTF-8')))return ['type',NULL];if(is_float($v)&&$v==0)$v=0.0;$values[]=$v;}if($hasNull)return ['null',NULL];$token=serialize($values);if(($bytes+=strlen($token))>8388608)throw new InvalidArgumentException('relation key bytes exceed 8 MiB');return [NULL,$token];};
 try{
 foreach($primary as $d=>$def){if(!$valid($def)||array_diff(array_keys($def),['table','fields']))return $fail('schema.primary['.$d.']','schema','invalid primary declaration');$seen=[];foreach($tables[$def['table']] as $i=>$row){$path='$['.json_encode($def['table']).']['.$i.']';[$error,$token]=$key($row,$def['fields']);if($error)return $fail($path,$error,'primary key fields must be present, nonnull scalars');if(isset($seen[$token]))return $fail($path,'unique','duplicate composite primary key; first row '.$seen[$token]);$seen[$token]=$i;}}
 foreach($foreign as $d=>$def){$ref=$def['references']??NULL;$null=$def['null']??'error';if(!$valid($def)||!$valid($ref)||array_diff(array_keys($def),['table','fields','references','null'])||array_diff(array_keys($ref),['table','fields'])||count($def['fields'])!==count($ref['fields'])||!in_array($null,['skip','error'],TRUE))return $fail('schema.foreign['.$d.']','schema','invalid foreign declaration');$index=[];foreach($tables[$ref['table']] as $i=>$row){[$error,$token]=$key($row,$ref['fields']);if($error)return $fail('$['.json_encode($ref['table']).']['.$i.']',$error,'referenced keys must be present nonnull scalars');$index[$token]=TRUE;}foreach($tables[$def['table']] as $i=>$row){$path='$['.json_encode($def['table']).']['.$i.']';[$error,$token]=$key($row,$def['fields']);if($error==='null'&&$null==='skip')continue;if($error)return $fail($path,$error,'foreign key fields must be present nonnull scalars');if(!isset($index[$token]))return $fail($path,'foreign','no matching referenced composite key');}}
 }catch(InvalidArgumentException $e){return $fail('$','limit',$e->getMessage());}
 return ['valid'=>TRUE,'issues'=>[],'kind'=>'relation','rows'=>$total,'keyFieldsChecked'=>$work];
}];
